{"content":"class_name ChunkData
extends RefCounted
## Horizontal voxel container for one chunk. Vertical full height 256.
## `blocks` stores block type, `meta` stores fluid level / flags / damage.
## World coordinates for a block at chunk (cx, cz) and local (lx, y, lz):
##   gx = cx * CHUNK_X + lx;  gz = cz * CHUNK_Z + lz

const CHUNK_X := 16
const CHUNK_Z := 16
const CHUNK_Y := 256

var chunk_pos := Vector2i.ZERO
var realm := 0
var blocks := PackedByteArray()
var meta := PackedByteArray()
var generated := false
var meshed := false
var dirty := false

# Generator may flag whole chunk as "no manual spawn allowed" e.g. nether has none.
var has_spawn_point := false


func _init(cpos: Vector2i, realm_id: int) -> void:
	chunk_pos = cpos
	realm = realm_id
	blocks.resize(CHUNK_X * CHUNK_Y * CHUNK_Z)
	meta.resize(CHUNK_X * CHUNK_Y * CHUNK_Z)


static func index(lx: int, y: int, lz: int) -> int:
	return (y * CHUNK_Z + lz) * CHUNK_X + lx


static func world_pos(cpos: Vector2i) -> Vector3i:
	return Vector3i(cpos.x * CHUNK_X, 0, cpos.y * CHUNK_Z)


static func to_chunk(v: Vector3i) -> Vector2i:
	return Vector2i(floori(float(v.x) / CHUNK_X), floori(float(v.z) / CHUNK_Z))


static func to_local(v: Vector3i) -> Vector3i:
	return Vector3i(posmod(v.x, CHUNK_X), clamp(v.y, 0, CHUNK_Y - 1), posmod(v.z, CHUNK_Z))


func in_bounds(lx: int, y: int, lz: int) -> bool:
	return lx >= 0 and lx < CHUNK_X and y >= 0 and y < CHUNK_Y and lz >= 0 and lz < CHUNK_Z


func get_block(lx: int, y: int, lz: int) -> int:
	if not in_bounds(lx, y, lz):
		return BlockRegistry.Block.AIR
	return blocks[index(lx, y, lz)]


func get_block_index(idx: int) -> int:
	return blocks[idx]


func set_block(lx: int, y: int, lz: int, id: int) -> void:
	if not in_bounds(lx, y, lz):
		return
	blocks[index(lx, y, lz)] = id


func get_meta(lx: int, y: int, lz: int) -> int:
	if not in_bounds(lx, y, lz):
		return 0
	return meta[index(lx, y, lz)]


func set_meta(lx: int, y: int, lz: int, m: int) -> void:
	if not in_bounds(lx, y, lz):
		return
	meta[index(lx, y, lz)] = m


## Level byte of a fluid block when meta is used for fluid level 0..15.
static func fluid_level(m: int) -> int:
	return m & 0x0F


static func set_fluid_level(m: int, level: int) -> int:
	return (m & 0xF0) | clamp(level, 0, 15)


func count_blocks() -> int:
	var n := 0
	for i in blocks.size():
		var b: int = blocks[i]
		if b != BlockRegistry.Block.AIR and not BlockRegistry.is_fluid(b):
			n += 1
	return n","filePath":"/home/work/voxel_survival/scripts/world/chunk_data.gd"}

